INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (1,1,1,NULL,'PRE_MATCH','7월 5일, YPR 기록의 첫 페이지','7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.','7월 5일 일요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\n\nA팀은 권태홍, 김병채, 김재홍 등 7명, B팀은 김동근, 변현우, 안휘진 등 6명, C팀은 구대현, 김응철, 이민선 등 6명으로 꾸려졌다.\n\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.','sample-template','wire_prompt_v2','FIRST_APPEARANCE:first_appearance_v1','PUBLISHED',1,'2026-07-04 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"권태홍\", \"김병채\", \"김재홍\", \"김현섭\", \"손원일\", \"윤영문\", \"전원재\"], \"teamCode\": \"A\", \"guestCount\": 0}, {\"members\": [\"김동근\", \"변현우\", \"안휘진\", \"윤기창\", \"이채현\", \"임우철\"], \"teamCode\": \"B\", \"guestCount\": 0}, {\"members\": [\"구대현\", \"김응철\", \"이민선\", \"이용준\", \"이종훈\", \"진선호\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 1, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"손원일\", \"memberId\": 1}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"손원일\", \"memberId\": 1}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 2, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김응철\", \"memberId\": 2}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김응철\", \"memberId\": 2}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 3, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 4, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"전원재\", \"m