INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (12,1,6,NULL,'SESSION_RECAP','김상균, 손원일 상대 5연패 끊었다','김상균은 오늘 손원일과의 맞대결에서 1승 0패로 앞서며 설욕에 성공했다.','8월 9일 YPR은 7경기를 치르며 총 17골을 기록했다. B팀이 2승 2무 1패로 가장 많은 승리를 챙겼다.\n\n득점 순위에서는 손원일(2골), 유창우(2골), 박영현(2골) 순으로 앞섰다.\n\n김상균은 오늘 손원일과의 맞대결에서 1승 0패로 앞서며 설욕에 성공했다. 이민선(6주), 유창우(5주), 박영현(5주)과 김동근(5주)이 연속 골 행진을 이어갔다.\n\n손원일 등 9명이 통산 30경기 출전 고지를 밟았다. 유창우가 통산 10골 고지를 밟았다.\n\n1경기  A 0 : 0 B\n2경기  B 2 : 0 C\n3경기  C 1 : 0 A\n4경기  A 3 : 0 B\n5경기  B 2 : 1 C\n6경기  C 2 : 2 A\n7경기  A 2 : 2 B','sample-template','wire_prompt_v2','ASSIST_COMBO:assist_combo_v1,MILESTONE_ACHIEVED:milestone_achieved_v1,RETURN_PLAYER_RESULT:return_player_result_v1,REVENGE_RESULT:revenge_result_v1,SCORING_STREAK:scoring_streak_v1,TITLE_AWARDED:title_awarded_v1','PUBLISHED',1,'2026-08-09 01:20:40.000',NULL,1,'{\"clubName\": \"YPR\", \"insights\": [{\"id\": 227, \"type\": \"REVENGE_RESULT\", \"facts\": {\"rival\": {\"name\": \"손원일\", \"memberId\": 1}, \"member\": {\"name\": \"김상균\", \"memberId\": 9}, \"members\": [{\"name\": \"김상균\", \"memberId\": 9}, {\"name\": \"손원일\", \"memberId\": 1}], \"outcome\": \"REVENGE\", \"drawsToday\": 2, \"matchesToday\": 3, \"matchesBefore\": 8, \"rivalWinsToday\": 0, \"memberWinsToday\": 1, \"rivalWinsBefore\": 6, \"lossStreakBefore\": 5, \"memberWinsBefore\": 2}, \"subject\": {\"name\": \"김상균\", \"memberId\": 9}, \"category\": \"PAIR\", \"importance\": 85}, {\"id\": 219, \"type\": \"SCORING_STREAK\", \"facts\": {\"member\": {\"name\": \"이민선\", \"memberId\": 15}, \"streak\": 6, \"goalsToday\": 1, \"streakUnit\": \"일정\"}, \"subject\": {\"name\": \"이민선\", \"memberId\": 15}, \"category\": \"STREAK\", \"importance\": 69}, {\"id\": 211, \"type\": \"SCORING_